insert into public.courses (id, slug, title, description) values
  ('a1000000-0000-4000-8000-000000000001', 'matematicas-1-eso', 'Matemáticas 1º ESO', 'Primer curso de matemáticas de la ESO.'),
  ('a1000000-0000-4000-8000-000000000002', 'matematicas-2-eso', 'Matemáticas 2º ESO', 'Segundo curso de matemáticas de la ESO.'),
  ('a1000000-0000-4000-8000-000000000003', 'matematicas-3-eso', 'Matemáticas 3º ESO', 'Tercer curso de matemáticas de la ESO.'),
  ('a1000000-0000-4000-8000-000000000004', 'matematicas-4-eso', 'Matemáticas 4º ESO (A)', 'Cuarto curso de matemáticas de la ESO.'),
  ('a1000000-0000-4000-8000-000000000017', 'matematicas-4-eso-b', 'Matemáticas 4º ESO (B)', 'Cuarto curso de matemáticas de la ESO, opción B.'),
  ('a1000000-0000-4000-8000-000000000005', 'matematicas-1-bachillerato', 'Matemáticas 1º Bachillerato', 'Primer curso de matemáticas de Bachillerato (10 temas, 129 lecciones).'),
  ('a1000000-0000-4000-8000-000000000018', 'matematicas-ccss-1-bachillerato', 'Matemáticas Aplicadas a las CCSS I (1º Bachillerato)', 'Matemáticas Aplicadas a las Ciencias Sociales I, 1º de Bachillerato (10 temas, 127 lecciones): números reales, matemática financiera, álgebra, funciones, límites, derivadas, estadística, probabilidad, combinatoria y distribuciones binomial y normal.'),
  ('a1000000-0000-4000-8000-000000000006', 'matematicas-2-bachillerato', 'Matemáticas 2º Bachillerato', 'Matemáticas II, 2º de Bachillerato (12 temas, 144 lecciones): matrices, determinantes, sistemas de ecuaciones, vectores, rectas y planos, geometría métrica, límites y continuidad, derivadas, representación de funciones, integrales, probabilidad y combinatoria, y distribuciones de probabilidad.'),
  ('a1000000-0000-4000-8000-000000000019', 'matematicas-ccss-2-bachillerato', 'Matemáticas Aplicadas a las CCSS II (2º Bachillerato)', 'Matemáticas Aplicadas a las Ciencias Sociales II, 2º de Bachillerato (8 temas, 94 lecciones): matrices, sistemas de ecuaciones, programación lineal, límites y continuidad, derivadas y representación de funciones, integrales, probabilidad, y estimación con contraste de hipótesis.'),
  ('a1000000-0000-4000-8000-000000000007', 'fisica-2-eso', 'Física 2º ESO', 'Segundo curso de Física y Química de la ESO.'),
  ('a1000000-0000-4000-8000-000000000008', 'fisica-3-eso', 'Física 3º ESO', 'Tercer curso de Física y Química de la ESO.'),
  ('a1000000-0000-4000-8000-000000000009', 'fisica-4-eso', 'Física 4º ESO', 'Cuarto curso de Física y Química de la ESO.'),
  ('a1000000-0000-4000-8000-000000000010', 'fisica-1-bachillerato', 'Física 1º Bachillerato', 'Primer curso de Física de Bachillerato.'),
  ('a1000000-0000-4000-8000-000000000011', 'fisica-2-bachillerato', 'Física 2º Bachillerato', 'Segundo curso de Física de Bachillerato.'),
  ('a1000000-0000-4000-8000-000000000012', 'tecnologia-1-eso', 'Tecnología 1º ESO', 'Introducción a la Tecnología: proceso tecnológico, expresión y comunicación gráfica, materiales, estructuras, mecanismos, electricidad, pensamiento computacional, tecnología sostenible, digitalización y comunicación de ideas.'),
  ('a1000000-0000-4000-8000-000000000013', 'tecnologia-2-eso', 'Tecnología 2º ESO', 'Tecnología y Digitalización: proyecto tecnológico, dibujo técnico y diseño digital, materiales y fabricación, estructuras y mecanismos, electricidad, programación, digitalización del entorno personal y tecnología sostenible.'),
  ('a1000000-0000-4000-8000-000000000014', 'tecnologia-3-eso', 'Tecnología 3º ESO', 'Tercer curso de Tecnología y Digitalización: proyectos, materiales, mecanismos, electrónica, control, robótica, redes y tecnología sostenible.'),
  ('a1000000-0000-4000-8000-000000000015', 'tecnologia-4-eso', 'Tecnología 4º ESO', 'Cuarto curso de Tecnología: proyectos de ingeniería, materiales y fabricación, sistemas mecánicos, electrónica, pensamiento computacional, automatización y robótica, tecnología sostenible y taller digital.'),
  ('a1000000-0000-4000-8000-000000000016', 'tecnologia-industrial-2-bachillerato', 'Tecnología Industrial II 2º Bachillerato', 'Estructura y ensayos de materiales, aleaciones, tratamientos térmicos, corrosión, principios de las máquinas, motores térmicos, circuitos frigoríficos, magnetismo, motores eléctricos, automatización neumática, oleohidráulica y sistemas automáticos de control.'),
  ('a1000000-0000-4000-8000-000000000020', 'tecnologia-ingenieria-1-bachillerato', 'Tecnología e Ingeniería I 1º Bachillerato', 'Proyectos de investigación y desarrollo, materiales y fabricación, sistemas mecánicos, sistemas eléctricos y electrónicos, programación, sistemas automáticos y tecnología sostenible.'),
  ('a1000000-0000-4000-8000-000000000021', 'tecnologia-ingenieria-2-bachillerato', 'Tecnología e Ingeniería II 2º Bachillerato (ampliación)', 'Ampliación de Tecnología Industrial II con los contenidos de Tecnología e Ingeniería II que ese curso no cubre: estructuras, corriente alterna, sistemas informáticos emergentes, proyectos de I+D y evaluación de impacto.'),
  ('a1000000-0000-4000-8000-000000000022', 'dibujo-tecnico-1-bachillerato', 'Dibujo Técnico I 1º Bachillerato', 'Geometría plana, sistemas de representación (diédrico, axonométrico, planos acotados y cónico), normalización y sistemas CAD, según el currículo de Dibujo Técnico I.'),
  ('a1000000-0000-4000-8000-000000000023', 'dibujo-tecnico-2-bachillerato', 'Dibujo Técnico II 2º Bachillerato', 'Transformaciones geométricas, tangencias, cónicas, diédrico avanzado, cuerpos, normalización industrial y proyecto, según el currículo de Dibujo Técnico II.');
