insert into public.lessons (id, module_id, title, summary, order_index, video_url) values
  ('a3000000-0000-4000-8000-000000000101', 'a2000000-0000-4000-8000-000000000001', '1. Origen de los números y aproximación por redondeo', 'Sistemas aditivos y posicional, decimal, y regla del redondeo con ejemplos del temario.', 1, null),
  ('a3000000-0000-4000-8000-000000000103', 'a2000000-0000-4000-8000-000000000001', '2. Suma y resta', 'Paréntesis, propiedades conmutativa y asociativa, problemas.', 2, null),
  ('a3000000-0000-4000-8000-000000000104', 'a2000000-0000-4000-8000-000000000001', '3. Multiplicación y división', 'Suma repetida, propiedades, reparto en partes iguales y divisiones exactas y con resto.', 3, null),
  ('a3000000-0000-4000-8000-000000000105', 'a2000000-0000-4000-8000-000000000001', '4. Orden de operaciones', 'Paréntesis, prioridad ×÷ frente a +− y orden de izquierda a derecha.', 4, null),
  ('a3000000-0000-4000-8000-000000000201', 'a2000000-0000-4000-8000-000000000002', '1. Potencias', 'Base, exponente, cuadrado, cubo, cálculo manual y con calculadora.', 1, null),
  ('a3000000-0000-4000-8000-000000000204', 'a2000000-0000-4000-8000-000000000002', '2. Raíz cuadrada', 'Inversa del cuadrado, cuadrados perfectos, raíz entera y calculadora.', 2, null),
  ('a3000000-0000-4000-8000-000000000301', 'a2000000-0000-4000-8000-000000000003', '1. Divisibilidad: múltiplos y divisores', 'División exacta, múltiplos infinitos y divisores por parejas.', 1, null),
  ('a3000000-0000-4000-8000-000000000303', 'a2000000-0000-4000-8000-000000000003', '2. Criterios de divisibilidad', 'Reglas para 2, 3, 4, 5, 6, 9, 10, 11 y 12 sin dividir.', 2, null),
  ('a3000000-0000-4000-8000-000000000304', 'a2000000-0000-4000-8000-000000000003', '3. Descomposición en factores primos', 'Primos y compuestos, criba de Eratóstenes y método de la línea vertical.', 3, null),
  ('a3000000-0000-4000-8000-000000000305', 'a2000000-0000-4000-8000-000000000003', '4. Mínimo común múltiplo', 'Múltiplos comunes, factores primos con mayor exponente y problemas de coincidencia.', 4, null),
  ('a3000000-0000-4000-8000-000000000306', 'a2000000-0000-4000-8000-000000000003', '5. Máximo común divisor', 'Divisores comunes, factores primos con menor exponente y problemas de reparto.', 5, null),
  ('a3000000-0000-4000-8000-000000000401', 'a2000000-0000-4000-8000-000000000004', '1. Los números enteros', 'Positivos y negativos, opuestos, recta numérica, valor absoluto y orden.', 1, null),
  ('a3000000-0000-4000-8000-000000000402', 'a2000000-0000-4000-8000-000000000004', '2. Sumas y restas de enteros', 'Mismo signo, distinto signo y expresiones con varios números.', 2, null),
  ('a3000000-0000-4000-8000-000000000403', 'a2000000-0000-4000-8000-000000000004', '3. Paréntesis en sumas y restas', 'Restar es sumar el opuesto; signo delante de un paréntesis y paréntesis anidados.', 3, null),
  ('a3000000-0000-4000-8000-000000000404', 'a2000000-0000-4000-8000-000000000004', '4. Multiplicación y división de enteros', 'Regla de los signos, división exacta y operaciones combinadas.', 4, null),
  ('a3000000-0000-4000-8000-000000000501', 'a2000000-0000-4000-8000-000000000005', '1. Los órdenes de unidades decimales', 'Décimas, centésimas y milésimas; lectura, orden en la recta y aproximación por redondeo.', 1, null),
  ('a3000000-0000-4000-8000-000000000502', 'a2000000-0000-4000-8000-000000000005', '2. Operaciones con números decimales', 'Suma y resta en columna, multiplicación y desplazamiento de la coma por 10, 100 y 1000.', 2, null),
  ('a3000000-0000-4000-8000-000000000503', 'a2000000-0000-4000-8000-000000000005', '3. División de números decimales', 'Divisor natural y decimal, cocientes periódicos y división entre 10, 100 y 1000.', 3, null),
  ('a3000000-0000-4000-8000-000000000601', 'a2000000-0000-4000-8000-000000000006', '1. Magnitudes y el Sistema Métrico Decimal', 'Medir es comparar con una unidad; origen del metro, litro y gramo; múltiplos y submúltiplos.', 1, null),
  ('a3000000-0000-4000-8000-000000000602', 'a2000000-0000-4000-8000-000000000006', '2. Medida de la longitud', 'Cambios de unidad con la tabla, forma compleja e incompleja, y unidades muy pequeñas y muy grandes.', 2, null),
  ('a3000000-0000-4000-8000-000000000603', 'a2000000-0000-4000-8000-000000000006', '3. Medida de la capacidad', 'El litro, sus múltiplos y submúltiplos, cambios de unidad y forma compleja.', 3, null),
  ('a3000000-0000-4000-8000-000000000604', 'a2000000-0000-4000-8000-000000000006', '4. Medida del peso', 'El gramo, el quintal y la tonelada, cambios de unidad y forma compleja.', 4, null),
  ('a3000000-0000-4000-8000-000000000605', 'a2000000-0000-4000-8000-000000000006', '5. Medida de la superficie', 'Unidad cuadrada, metro cuadrado (de 100 en 100), unidades agrarias y cambios de unidad.', 5, null),
  ('a3000000-0000-4000-8000-000000001701', 'a2000000-0000-4000-8000-000000000017', '1. Parte de la unidad', 'La fracción como parte de un todo: numerador, denominador y representación.', 1, null),
  ('a3000000-0000-4000-8000-000000001702', 'a2000000-0000-4000-8000-000000000017', '2. La fracción como operador', 'Calcular la fracción de una cantidad: dividir y multiplicar.', 2, null),
  ('a3000000-0000-4000-8000-000000001703', 'a2000000-0000-4000-8000-000000000017', '3. Fracciones y números decimales', 'Una fracción es una división: paso de fracción a decimal.', 3, null),
  ('a3000000-0000-4000-8000-000000001704', 'a2000000-0000-4000-8000-000000000017', '4. Fracciones equivalentes', 'Misma porción con distinta escritura; amplificar y simplificar.', 4, null),
  ('a3000000-0000-4000-8000-000000001705', 'a2000000-0000-4000-8000-000000000017', '5. Problemas con fracciones', 'Problemas de fracción de una cantidad y de la fracción que representa.', 5, null),
  ('a3000000-0000-4000-8000-000000001801', 'a2000000-0000-4000-8000-000000000018', '1. Reducción a común denominador', 'Comparar y sumar exige trozos del mismo tamaño.', 1, null),
  ('a3000000-0000-4000-8000-000000001802', 'a2000000-0000-4000-8000-000000000018', '2. Suma y resta de fracciones', 'Con igual y con distinto denominador.', 2, null),
  ('a3000000-0000-4000-8000-000000001803', 'a2000000-0000-4000-8000-000000000018', '3. Multiplicación y división de fracciones', 'Producto y cociente de fracciones.', 3, null),
  ('a3000000-0000-4000-8000-000000001804', 'a2000000-0000-4000-8000-000000000018', '4. Problemas con fracciones', 'Situaciones del total y del resto.', 4, null),
  ('a3000000-0000-4000-8000-000000001901', 'a2000000-0000-4000-8000-000000000019', '1. Relación de proporcionalidad entre magnitudes', 'Magnitudes directamente proporcionales y su tabla.', 1, null),
  ('a3000000-0000-4000-8000-000000001902', 'a2000000-0000-4000-8000-000000000019', '2. Problemas de proporcionalidad directa e inversa', 'Reducción a la unidad y regla de tres.', 2, null),
  ('a3000000-0000-4000-8000-000000001903', 'a2000000-0000-4000-8000-000000000019', '3. Porcentajes', 'Un porcentaje son partes de cada 100; calcular el a % de una cantidad.', 3, null),
  ('a3000000-0000-4000-8000-000000001904', 'a2000000-0000-4000-8000-000000000019', '4. Aumentos y disminuciones porcentuales', 'Sumar el incremento, restar la rebaja y atajo multiplicativo.', 4, null),
  ('a3000000-0000-4000-8000-000000002001', 'a2000000-0000-4000-8000-000000000020', '1. Letras en vez de números', 'Una cantidad desconocida se escribe con una letra.', 1, null),
  ('a3000000-0000-4000-8000-000000002002', 'a2000000-0000-4000-8000-000000000020', '2. Expresiones algebraicas', 'Operaciones indicadas con letras y monomios.', 2, null),
  ('a3000000-0000-4000-8000-000000002003', 'a2000000-0000-4000-8000-000000000020', '3. Ecuaciones', 'Ecuación o identidad: ¿para qué valores se cumple?', 3, null),
  ('a3000000-0000-4000-8000-000000002004', 'a2000000-0000-4000-8000-000000000020', '4. Primeras técnicas de resolución', 'Lo que suma pasa restando y lo que multiplica pasa dividiendo.', 4, null),
  ('a3000000-0000-4000-8000-000000002005', 'a2000000-0000-4000-8000-000000000020', '5. Ecuaciones de primer grado', 'Reducir y transponer hasta dejar la x sola.', 5, null),
  ('a3000000-0000-4000-8000-000000002006', 'a2000000-0000-4000-8000-000000000020', '6. Problemas con ecuaciones', 'Nombrar la incógnita, plantear, resolver y comprobar.', 6, null),
  ('a3000000-0000-4000-8000-000000002101', 'a2000000-0000-4000-8000-000000000021', '1. Rectas, semirrectas y segmentos', 'Recta, semirrecta, segmento y posiciones de dos rectas.', 1, null),
  ('a3000000-0000-4000-8000-000000002102', 'a2000000-0000-4000-8000-000000000021', '2. Mediatriz y bisectriz', 'Qué son y cómo se trazan con regla y compás.', 2, null),
  ('a3000000-0000-4000-8000-000000002103', 'a2000000-0000-4000-8000-000000000021', '3. Ángulos', 'Elementos, tipos según su amplitud y según su posición.', 3, null),
  ('a3000000-0000-4000-8000-000000002104', 'a2000000-0000-4000-8000-000000000021', '4. Ángulos entre paralelas', 'Una secante corta a dos paralelas: ángulos iguales y suplementarios.', 4, null),
  ('a3000000-0000-4000-8000-000000002105', 'a2000000-0000-4000-8000-000000000021', '5. Medida de ángulos', 'Grados y minutos: medir y operar.', 5, null),
  ('a3000000-0000-4000-8000-000000002106', 'a2000000-0000-4000-8000-000000000021', '6. Ángulos en los polígonos', 'Suma de ángulos de triángulos, cuadriláteros y polígonos.', 6, null),
  ('a3000000-0000-4000-8000-000000002201', 'a2000000-0000-4000-8000-000000000022', '1. Triángulos', 'Clasificación, medianas y baricentro, alturas y ortocentro.', 1, null),
  ('a3000000-0000-4000-8000-000000002202', 'a2000000-0000-4000-8000-000000000022', '2. Cuadriláteros', 'Paralelogramos, trapecios y trapezoides.', 2, null),
  ('a3000000-0000-4000-8000-000000002203', 'a2000000-0000-4000-8000-000000000022', '3. Polígonos regulares', 'Centro, radio y apotema de un polígono regular.', 3, null),
  ('a3000000-0000-4000-8000-000000002204', 'a2000000-0000-4000-8000-000000000022', '4. Circunferencia', 'Elementos, recta y circunferencia, y dos circunferencias.', 4, null),
  ('a3000000-0000-4000-8000-000000002205', 'a2000000-0000-4000-8000-000000000022', '5. Poliedros y poliedros regulares', 'Elementos, fórmula de Euler y sólidos platónicos.', 5, null),
  ('a3000000-0000-4000-8000-000000002206', 'a2000000-0000-4000-8000-000000000022', '6. Prismas', 'Prismas, ortoedros y prismas regulares.', 6, null),
  ('a3000000-0000-4000-8000-000000002207', 'a2000000-0000-4000-8000-000000000022', '7. Pirámides', 'Pirámides y pirámides regulares.', 7, null),
  ('a3000000-0000-4000-8000-000000002208', 'a2000000-0000-4000-8000-000000000022', '8. Cuerpos de revolución', 'Cilindro, cono y esfera.', 8, null),
  ('a3000000-0000-4000-8000-000000002301', 'a2000000-0000-4000-8000-000000000023', '1. Medidas en los cuadriláteros', 'Área y perímetro de rectángulos, paralelogramos, rombos y trapecios.', 1, null),
  ('a3000000-0000-4000-8000-000000002302', 'a2000000-0000-4000-8000-000000000023', '2. Área de un triángulo', 'Mitad de un paralelogramo; triángulo rectángulo.', 2, null),
  ('a3000000-0000-4000-8000-000000002303', 'a2000000-0000-4000-8000-000000000023', '3. Medidas en los polígonos', 'Descomposición en triángulos y polígonos regulares.', 3, null),
  ('a3000000-0000-4000-8000-000000002304', 'a2000000-0000-4000-8000-000000000023', '4. Medidas en el círculo', 'Número pi, longitud, área y corona circular.', 4, null),
  ('a3000000-0000-4000-8000-000000002401', 'a2000000-0000-4000-8000-000000000024', '1. Coordenadas cartesianas', 'Ejes, origen, cuadrantes y localización de puntos.', 1, null),
  ('a3000000-0000-4000-8000-000000002402', 'a2000000-0000-4000-8000-000000000024', '2. Información mediante puntos', 'Leer dos magnitudes en un diagrama de puntos.', 2, null),
  ('a3000000-0000-4000-8000-000000002403', 'a2000000-0000-4000-8000-000000000024', '3. Interpretación de gráficas', 'Variables independiente y dependiente; leer tramos.', 3, null),
  ('a3000000-0000-4000-8000-000000002404', 'a2000000-0000-4000-8000-000000000024', '4. Distribuciones estadísticas', 'Variables, tablas de frecuencias absolutas y relativas.', 4, null),
  ('a3000000-0000-4000-8000-000000002405', 'a2000000-0000-4000-8000-000000000024', '5. Media, mediana y moda', 'Los tres parámetros de centralización.', 5, null),
  ('a3000000-0000-4000-8000-000000002406', 'a2000000-0000-4000-8000-000000000024', '6. Gráficos estadísticos', 'Barras, histograma, polígono y sectores.', 6, null),
  ('a3000000-0000-4000-8000-000000002501', 'a2000000-0000-4000-8000-000000000025', '1. Experimento aleatorio y determinista', 'Qué se puede predecir y qué no.', 1, null),
  ('a3000000-0000-4000-8000-000000002502', 'a2000000-0000-4000-8000-000000000025', '2. Espacio muestral y sucesos elementales', 'Todos los resultados posibles.', 2, null),
  ('a3000000-0000-4000-8000-000000002503', 'a2000000-0000-4000-8000-000000000025', '3. Sucesos, suceso seguro e imposible', 'Sucesos formados por resultados elementales.', 3, null),
  ('a3000000-0000-4000-8000-000000002504', 'a2000000-0000-4000-8000-000000000025', '4. Frecuencia absoluta y relativa', 'Frecuencias y estabilidad al repetir.', 4, null),
  ('a3000000-0000-4000-8000-000000002505', 'a2000000-0000-4000-8000-000000000025', '5. Probabilidad y regla de Laplace', 'Casos favorables entre casos posibles.', 5, null),
  ('a3000000-0000-4000-8000-000000002601', 'a2000000-0000-4000-8000-000000000026', '1. Divisibilidad: múltiplos y divisores', 'Relación de divisibilidad, múltiplos, divisores y la suma de múltiplos.', 1, null),
  ('a3000000-0000-4000-8000-000000002602', 'a2000000-0000-4000-8000-000000000026', '2. Criterios de divisibilidad', 'Reglas para 2, 3, 4, 5, 6, 9, 10, 11 y 12 sin dividir.', 2, null),
