  ('a3000000-0000-4000-8000-000000017703', 'a2000000-0000-4000-8000-000000000177', '3. Ahorro energético en edificios y certificado energético', 'Demanda, sistema y etiqueta energética.', 3, null),
  ('a3000000-0000-4000-8000-000000017704', 'a2000000-0000-4000-8000-000000000177', '4. Economía circular, reparación y obsolescencia', 'Las erres y reparar frente a comprar.', 4, null),
  ('a3000000-0000-4000-8000-000000017705', 'a2000000-0000-4000-8000-000000000177', '5. Impacto social y ambiental de la tecnología', 'Huella, residuos electrónicos y brecha digital.', 5, null),
  ('a3000000-0000-4000-8000-000000017706', 'a2000000-0000-4000-8000-000000000177', '6. Accesibilidad y diseño universal', 'Rampas, contraste y diseño para todos.', 6, null),
