  ('a3000000-0000-4000-8000-000000017805', 'a2000000-0000-4000-8000-000000000178', '5. Montaje de circuitos: soldadura y placas', 'PCB, anchura de pistas y soldadura.', 5, null),
  ('a3000000-0000-4000-8000-000000017806', 'a2000000-0000-4000-8000-000000000178', '6. Pruebas, documentación y proyecto de taller', 'Pruebas, memoria y proyecto final.', 6, null),
