  ('a3000000-0000-4000-8000-000000006602', 'a2000000-0000-4000-8000-000000000066', '2. Fuerzas y energía de enlace', 'Atracción y repulsión entre átomos, distancia de equilibrio y energía de enlace.', 2, null),
  ('a3000000-0000-4000-8000-000000006603', 'a2000000-0000-4000-8000-000000000066', '3. Estructura electrónica y electronegatividad', 'Gases nobles, elementos electropositivos y electronegativos y escala de electronegatividad.', 3, null),
  ('a3000000-0000-4000-8000-000000006604', 'a2000000-0000-4000-8000-000000000066', '4. Enlace iónico', 'Transferencia de electrones, tamaño de los iones y propiedades de los cristales iónicos.', 4, null),
  ('a3000000-0000-4000-8000-000000006605', 'a2000000-0000-4000-8000-000000000066', '5. Enlace covalente y el carbono', 'Pares compartidos, enlaces múltiples e hibridación sp³ del carbono.', 5, null),
  ('a3000000-0000-4000-8000-000000006606', 'a2000000-0000-4000-8000-000000000066', '6. Enlace metálico y enlaces secundarios', 'Nube electrónica, fuerzas de Van der Waals, puente de hidrógeno y energía de enlace.', 6, null),
