  ('a3000000-0000-4000-8000-000000006608', 'a2000000-0000-4000-8000-000000000066', '8. Alotropía y materiales amorfos', 'Cambios de estructura con la temperatura y sólidos sin orden de largo alcance.', 8, null),
  ('a3000000-0000-4000-8000-000000006609', 'a2000000-0000-4000-8000-000000000066', '9. Propiedades mecánicas y tipos de ensayos', 'Deformación elástica y plástica, propiedades mecánicas y clasificación de los ensayos.', 9, null),
