  ('a3000000-0000-4000-8000-000000006612', 'a2000000-0000-4000-8000-000000000066', '12. Ley de Hooke y tensión de trabajo', 'Módulo elástico, alargamiento, coeficiente de seguridad y tensión máxima de trabajo.', 12, null),
  ('a3000000-0000-4000-8000-000000006613', 'a2000000-0000-4000-8000-000000000066', '13. Ensayo de dureza Brinell', 'Bola, huella, superficie del casquete, dureza HB y cargas recomendadas.', 13, null),
